func (q *Queries) LockProjectConfig(ctx context.Context, id pgtype.UUID) ([]byte, error) {
	row := q.db.QueryRow(ctx, lockProjectConfig, id)
	var process_config []byte
	err := row.Scan(&process_config)
	return process_config, err
}

